import{_ as i,o as a,c as e,aO as n}from"./chunks/framework.vjUPZZJn.js";const o=JSON.parse('{"title":"iceoryx2 命令行工具：服务发现、数据注入与录制回放","description":"","frontmatter":{"date":"2026-11-09T10:20:00.000Z","title":"iceoryx2 命令行工具：服务发现、数据注入与录制回放","source":"[[1-知识/中间件/iceoryx2/06 命令行工具]]","tags":["中间件","教程手册","iceoryx2","调试"],"categories":["机器人"],"permalink":"/pages/e180ea"},"headers":[],"relativePath":"机器人/iceoryx2 命令行工具：服务发现、数据注入与录制回放.md","filePath":"机器人/iceoryx2 命令行工具：服务发现、数据注入与录制回放.md","lastUpdated":1794223026000}'),t={name:"机器人/iceoryx2 命令行工具：服务发现、数据注入与录制回放.md"};function l(p,s,h,r,d,c){return a(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="iceoryx2-命令行工具-服务发现、数据注入与录制回放" tabindex="-1">iceoryx2 命令行工具：服务发现、数据注入与录制回放 <a class="header-anchor" href="#iceoryx2-命令行工具-服务发现、数据注入与录制回放" aria-label="Permalink to &quot;iceoryx2 命令行工具：服务发现、数据注入与录制回放&quot;">​</a></h1> <p>共享内存通信的系统排查起来有个天然困难：数据不经过网络，tcpdump 这类抓包工具全无用武之地。iceoryx2 提供了一套 <code>iox2</code> 命令行工具补上这块空白：查看节点与服务状态、订阅实时数据、手动注入消息与事件、录制回放整段通信。本文按「观测 → 注入 → 录制回放」的排查思路整理常用命令，适合正在用 iceoryx2 做开发的工程师。</p> <h2 id="安装与总览" tabindex="-1">安装与总览 <a class="header-anchor" href="#安装与总览" aria-label="Permalink to &quot;安装与总览&quot;">​</a></h2> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> iceoryx2-cli</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>安装后 <code>iox2</code> 按子命令分发到各子工具，<code>iox2 --list</code> 查看全部子命令。</p> <h2 id="节点与服务发现" tabindex="-1">节点与服务发现 <a class="header-anchor" href="#节点与服务发现" aria-label="Permalink to &quot;节点与服务发现&quot;">​</a></h2> <p>排查从「现在有哪些参与方、哪些服务」开始：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 列出所有节点</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iox2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查看节点详情</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iox2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> details</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 00000000067ab750000005550000dcf7</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 列出所有服务</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iox2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>节点 ID 是一个长十六进制数字，<code>node details</code> 可以看到该节点的详细信息。服务异常、节点未注册之类的问题，先在这里确认现场。</p> <h2 id="观测-订阅数据与监听事件" tabindex="-1">观测：订阅数据与监听事件 <a class="header-anchor" href="#观测-订阅数据与监听事件" aria-label="Permalink to &quot;观测：订阅数据与监听事件&quot;">​</a></h2> <p>不动任何进程，从外部看服务里流动的数据：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 订阅服务的实时数据流</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iox2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> subscribe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;distance_to_obstacle&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 监听服务的事件通知（检查通知是否送达）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iox2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> listen</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;distance_to_obstacle&quot;</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><code>subscribe</code> 用于发布订阅类服务——数据没按预期发送、字段值不对，直接在这里看；<code>listen</code> 用于事件类服务——事件通知是否真的发出去了，一听便知。</p> <h2 id="注入-制造测试场景" tabindex="-1">注入：制造测试场景 <a class="header-anchor" href="#注入-制造测试场景" aria-label="Permalink to &quot;注入：制造测试场景&quot;">​</a></h2> <p>排查不应只靠等现场复现，<code>iox2</code> 可以主动注入数据制造条件：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 发送事件通知，直接触发对端响应</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iox2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> notify</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --event-id</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --num</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> distance_to_obstacle</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>手动发布一条消息需要先拿到数据的十六进制表示（<code>--message</code> 参数按十六进制字节传 payload）：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iox2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> publish</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> IOX2DUMP</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --type-name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Distance</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --type-size</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 16</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --type-alignment</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --type-variant</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FIXEDSIZE</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repetitions</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --message</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;09 00 00 00 1b 00 00 00 ae 47 e1 7a 14 8d bc 40&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  distance_to_obstacle</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>参数里 <code>--type-size</code>、<code>--type-alignment</code>、<code>--type-variant</code> 必须与接收方类型定义一致，否则对方按自己的布局解析会得到乱数据。拿不准布局时，可以先用 <code>subscribe</code> 观测一条正常报文的十六进制，照着构造。</p> <h2 id="录制与回放" tabindex="-1">录制与回放 <a class="header-anchor" href="#录制与回放" aria-label="Permalink to &quot;录制与回放&quot;">​</a></h2> <p>现场数据可遇不可求，录制下来离线复现：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 录制数据流（-t 指定时长秒数，-o 指定输出文件）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iox2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> record</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> record.dat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;distance_to_obstacle&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 回放</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iox2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> replay</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> record.dat</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>录制文件包含两部分：元数据（服务信息、消息模式等）与带时间戳的十六进制有效载荷。典型用法是现场录一段异常数据，回办公室用 <code>replay</code> 反复回放给修复后的程序，验证行为是否正确，不用等下一次现场异常。</p> <h2 id="适用场景速查" tabindex="-1">适用场景速查 <a class="header-anchor" href="#适用场景速查" aria-label="Permalink to &quot;适用场景速查&quot;">​</a></h2> <table tabindex="0"><thead><tr><th>症状</th> <th>工具</th></tr></thead> <tbody><tr><td>节点或服务状态异常</td> <td><code>node list</code> / <code>node details</code> / <code>service list</code></td></tr> <tr><td>数据未按预期发送、值可疑</td> <td><code>service subscribe</code></td></tr> <tr><td>事件通知疑似丢失</td> <td><code>service listen</code></td></tr> <tr><td>需要模拟特定输入触发问题</td> <td><code>service notify</code> / <code>service publish</code></td></tr> <tr><td>算法修复后需要复现当时数据</td> <td><code>service record</code> + <code>service replay</code></td></tr></tbody></table> <h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2> <ul><li>共享内存通信排查靠 <code>iox2</code>，网络抓包工具看不到数据</li> <li>观测三件套：<code>service list</code> 看现场、<code>subscribe</code> 看数据、<code>listen</code> 看事件</li> <li>注入数据时类型布局参数必须与接收方一致</li> <li>录制回放让「异常复现」不再依赖现场条件</li></ul>`,47)])])}const F=i(t,[["render",l]]);export{o as __pageData,F as default};
